18	// claudettuiQuotaFreshness is the constant freshness window for claude-tui quota
19	// evidence. Matches claude's default of 15 minutes.
20	const claudettuiQuotaFreshness = 15 * time.Minute
21	
22	// claudettuiAccountFreshness is the constant freshness window for claude-tui
23	// account evidence. Claude-tui embeds account info in its quota probe so the
24	// account refresh cadence matches quota.
25	const claudettuiAccountFreshness = claudettuiQuotaFreshness
26	
27	// supportedLimitIDs is the stable public set of Windows[].LimitID values
28	// claude-tui's quota probe emits. Must match claude's set.
29	// Mirrored in doc.go for human readers.
30	var supportedLimitIDs = []string{
31		"session",
32		"weekly-all",
33		"weekly-sonnet",
34		"extra",
35	}
36	
37	// supportedAliases is the stable public set of family aliases
38	// ResolveModelAlias recognizes. Mirrored in doc.go for human readers.
39	var supportedAliases = []string{"sonnet", "opus", "haiku"}
40	
41	// refreshGroup serializes concurrent RefreshQuota / RefreshAccount calls
42	// across all *Harness instances. Per CONTRACT-004 invariant #6 Harnesses are
43	// stateless wrappers — sharing the singleflight group at package scope
44	// keeps single-flight semantics correct when callers construct fresh
45	// harness instances per call (which the dispatcher does today).
46	var refreshGroup singleflight.Group
47	
48	// QuotaProbeFunc is the signature of the PTY-quota probe that
49	// Harness.RefreshQuota delegates to. Exposing it as a named type keeps
50	// the SetCaptureForTest seam decoupled from the internal ptyquota
51	// package; the test seam discards the ptyquota.Result that the live
52	// probe returns.
53	type QuotaProbeFunc func(ctx context.Context, timeout time.Duration) ([]harnesses.QuotaWindow, *harnesses.AccountInfo, error)
54	
55	// captureQuotaProbe is the live PTY probe used by RefreshQuota. It is a
56	// package-level variable so tests can swap it via SetCaptureForTest
57	// without spawning the claude binary. The default delegates to
58	// captureClaudeTuiQuotaViaPTY and discards the ptyquota.Result.
59	var captureQuotaProbe QuotaProbeFunc = func(ctx context.Context, timeout time.Duration) ([]harnesses.QuotaWindow, *harnesses.AccountInfo, error) {
60		windows, account, _, err := captureClaudeTuiQuotaViaPTY(ctx, timeout)
61		return windows, account, err
62	}
63	
64	// SetCaptureForTest swaps the package-level PTY probe used by
65	// Harness.RefreshQuota and returns a restore function. Production code
66	// MUST NOT call this — it exists so service-level tests can inject
67	// deterministic PTY responses while exercising the real cache I/O
68	// inside Harness.refreshQuotaLocked. The call also forgets any
69	// in-flight RefreshQuota cohort so the next caller runs a fresh
70	// single-flight execution against the new probe instead of piggybacking
71	// on a prior test's probe.
72	func SetCaptureForTest(fn QuotaProbeFunc) func() {
73		prev := captureQuotaProbe
74		captureQuotaProbe = fn
75		refreshGroup.Forget("claudetui:refresh-quota")
76		return func() {
77			captureQuotaProbe = prev
78			refreshGroup.Forget("claudetui:refresh-quota")
79		}
80	}
81	
82	// QuotaStatus implements harnesses.QuotaHarness. It reads the cached
83	// snapshot owned by the shared anthropic cache and projects it onto QuotaStatus.
84	// A missing or undecodable cache is reported as State=QuotaUnavailable on
85	// a valid QuotaStatus value (no error) per CONTRACT-004 §"Errors are
86	// reserved for call failure."
87	func (h *Harness) QuotaStatus(ctx context.Context, now time.Time) (harnesses.QuotaStatus, error) {
88		if err := ctx.Err(); err != nil {
89			return harnesses.QuotaStatus{}, err
90		}
91		snap, ok := anthropic.ReadClaudeQuota()
92		if !ok || snap == nil {
93			return harnesses.QuotaStatus{
94				Source:            "cache",
95				State:             harnesses.QuotaUnavailable,
96				RoutingPreference: harnesses.RoutingPreferenceUnknown,
97				Reason:            "no cached snapshot",
98			}, nil
99		}
100		return claudettuiQuotaStatusFromSnapshot(snap, now), nil
101	}
102	
103	// RefreshQuota implements harnesses.QuotaHarness. It probes the claude
104	// CLI via PTY unconditionally and persists the result through the shared
105	// harness cache. Single-flight per harness: concurrent callers
106	// share one cohort and observe the just-written cached state. Probe
107	// failure (binary missing, PTY error, parse failure) is reported as
108	// State=QuotaUnavailable on a valid QuotaStatus value, not as an error.
109	func (h *Harness) RefreshQuota(ctx context.Context) (harnesses.QuotaStatus, error) {
110		if err := ctx.Err(); err != nil {
111			return harnesses.QuotaStatus{}, err
112		}
113		v, err, _ := refreshGroup.Do("claudetui:refresh-quota", func() (any, error) {
114			return h.refreshQuotaLocked(ctx), nil
115		})
116		if err != nil {
117			return harnesses.QuotaStatus{}, err
118		}
119		return v.(harnesses.QuotaStatus), nil
120	}
121	
122	// refreshQuotaLocked is the single-flight critical section. It probes
123	// PTY, writes the cache on success, and returns the projected status.
124	// Probe failure is folded into State=QuotaUnavailable.
125	func (h *Harness) refreshQuotaLocked(ctx context.Context) harnesses.QuotaStatus {
126		now := time.Now()
127		timeout := claudettuiQuotaFreshness
128		if deadline, ok := ctx.Deadline(); ok {
129			remaining := time.Until(deadline)
130			if remaining > 0 && remaining < timeout {
131				timeout = remaining
132			}
133		}
134		windows, account, err := captureQuotaProbe(ctx, timeout)
135		if err != nil {
136			state := harnesses.QuotaUnavailable
137			reason := err.Error()
138			if strings.Contains(strings.ToLower(reason), "not found in path") {
139				state = harnesses.QuotaUnauthenticated
140			}
141			return harnesses.QuotaStatus{
142				Source:            "pty",
143				CapturedAt:        now.UTC(),
144				State:             state,
145				RoutingPreference: harnesses.RoutingPreferenceUnknown,
146				Reason:            reason,
147			}
148		}
149		snap := claudettuiQuotaSnapshotFromWindows(windows, account)
150		if path, pathErr := anthropic.ClaudeQuotaCachePath(); pathErr == nil {
151			_ = anthropic.WriteClaudeQuota(path, snap)
152		}
153		return claudettuiQuotaStatusFromSnapshot(&snap, now)
154	}
