363	func quotaRecord(windows []harnesses.QuotaWindow, metadata map[string]any) cassette.QuotaRecord {
364		records := make([]map[string]any, 0, len(windows))
365		for _, window := range windows {
366			records = append(records, map[string]any{
367				"name":           window.Name,
368				"limit_id":       window.LimitID,
369				"window_minutes": window.WindowMinutes,
370				"used_percent":   window.UsedPercent,
371				"resets_at":      window.ResetsAt,
372				"state":          window.State,
373			})
374		}
375		accountClass, _ := metadata["plan_type"].(string)
376		return cassette.QuotaRecord{
377			Source:            "pty",
378			Status:            string(ptyquota.StatusOK),
379			CapturedAt:        time.Now().UTC().Format(time.RFC3339),
380			FreshnessWindow:   claudettuiQuotaFreshness.String(),
381			StalenessBehavior: "stale quota evidence keeps Claude out of automatic routing and is treated as limited",
382			AccountClass:      accountClass,
383			Windows:           records,
384			Metadata:          metadata,
385		}
386	}
387	
388	func accountPlan(account *harnesses.AccountInfo) string {
389		if account == nil {
390			return ""
391		}
392		return account.PlanType
393	}
