396	// Both claude and claude-tui use the same /usage output format, so they share the same parser.
397	func parseClaudeTuiUsageOutput(text string) ([]harnesses.QuotaWindow, *harnesses.AccountInfo) {
398		return anthropic.ParseClaudeUsageOutput(text)
399	}
