// DefaultModelSnapshot implements harnesses.ModelDiscoveryHarness. It drives the
// live PTY discovery probe and caches the result per ADR-012. Returns
// ErrModelDiscoveryEvidenceMissing on PTY failure or timeout per the
// no-static-fallback principle.
func (h *Harness) DefaultModelSnapshot() (harnesses.ModelDiscoverySnapshot, error) {
	if modelDiscoveryCache == nil {
		return harnesses.ModelDiscoverySnapshot{}, harnesses.ErrModelDiscoveryEvidenceMissing
	}

	source := discoverycache.Source{
		Tier:             "discovery",
		Name:             "claude-tui",
		TTL:              modelDiscoveryFreshness,
		RefreshDeadline:  modelDiscoveryRefreshDeadline,
	}

	// Read cache; if fresh, return cached snapshot without probing.
	cached, err := modelDiscoveryCache.Read(source)
	if err == nil && cached.Fresh && cached.Data != nil {
		var snapshot harnesses.ModelDiscoverySnapshot
		if umErr := json.Unmarshal(cached.Data, &snapshot); umErr == nil {
			return snapshot, nil
		}
	}

	// Cache was stale or absent; run a refresh (possibly blocking on in-flight refresh).
	refreshErr := modelDiscoveryCache.Refresh(source, func(ctx context.Context) ([]byte, error) {
		return h.probeModelDiscovery(ctx)
	})
	if refreshErr != nil {
		return harnesses.ModelDiscoverySnapshot{}, fmt.Errorf("model discovery refresh: %w", refreshErr)
	}

	// Read the freshly written cache.
	result, err := modelDiscoveryCache.Read(source)
	if err != nil {
		return harnesses.ModelDiscoverySnapshot{}, fmt.Errorf("model discovery cache read: %w", err)
	}
	if result.Data == nil {
		return harnesses.ModelDiscoverySnapshot{}, harnesses.ErrModelDiscoveryEvidenceMissing
	}

	var snapshot harnesses.ModelDiscoverySnapshot
	if err := json.Unmarshal(result.Data, &snapshot); err != nil {
		return harnesses.ModelDiscoverySnapshot{}, fmt.Errorf("model discovery unmarshal: %w", err)
	}
	if len(snapshot.Models) == 0 {
		return harnesses.ModelDiscoverySnapshot{}, harnesses.ErrModelDiscoveryEvidenceMissing
	}
	return snapshot, nil
}

// probeModelDiscovery drives the live PTY probe and returns the JSON-encoded snapshot.
// This is the Refresher function injected into the discoverycache.
func (h *Harness) probeModelDiscovery(ctx context.Context) ([]byte, error) {
	snapshot, err := readClaudeTuiModelDiscoveryViaPTY(ctx, modelDiscoveryRefreshDeadline)
	if err != nil {
		return nil, err
	}
	if len(snapshot.Models) == 0 {
		return nil, harnesses.ErrModelDiscoveryEvidenceMissing
	}
	return json.Marshal(snapshot)
}

// ResolveModelAlias implements harnesses.ModelDiscoveryHarness. Returns
// ErrAliasNotResolvable when the supplied family is not recognized or
// the snapshot has no concrete model matching the family.
func (h *Harness) ResolveModelAlias(family string, snapshot harnesses.ModelDiscoverySnapshot) (string, error) {
	normalized := strings.ToLower(strings.TrimSpace(family))
	if !isSupportedClaudeTuiAlias(normalized) {
		return "", harnesses.ErrAliasNotResolvable
	}
	resolved := resolveClaudeTuiFamilyAlias(normalized, snapshot)
	if resolved == "" {
		return "", harnesses.ErrAliasNotResolvable
	}
	return resolved, nil
}

// SupportedAliases implements harnesses.ModelDiscoveryHarness.
func (h *Harness) SupportedAliases() []string {
	return append([]string(nil), supportedAliases...)
}

// discoveryCachePath returns the directory for the discovery cache, creating it if needed.
func discoveryCachePath() (string, error) {
	cacheDir, err := os.UserCacheDir()
	if err != nil {
		return "", err
	}
	path := filepath.Join(cacheDir, "fizeau")
	if err := os.MkdirAll(path, 0o750); err != nil {
		return "", err
	}
	return path, nil
}

// latestClaudeTuiFamilyVersion finds the highest version of the requested family
// from the snapshot's model list, returning empty string if no match is found.
func latestClaudeTuiFamilyVersion(family string, models []string) string {
	prefix := family + "-"
	best := ""
	var bestParts []int
	for _, model := range models {
		modelLower := strings.ToLower(strings.TrimSpace(model))
		if !strings.HasPrefix(modelLower, prefix) {
			continue
		}
		parts, ok := parseClaudeTuiVersionParts(strings.TrimPrefix(modelLower, prefix))
		if !ok {
			continue
		}
		if best == "" || compareClaudeTuiVersionParts(parts, bestParts) > 0 {
			best = modelLower
			bestParts = parts
		}
	}
	return best
}

// parseClaudeTuiVersionParts splits a version string into numeric components.
func parseClaudeTuiVersionParts(version string) ([]int, bool) {
	version = strings.ReplaceAll(version, "-", ".")
	raw := strings.Split(version, ".")
	if len(raw) == 0 {
		return nil, false
	}
	parts := make([]int, 0, len(raw))
	for _, part := range raw {
		if part == "" {
			return nil, false
		}
		n := 0
		for _, r := range part {
			if r < '0' || r > '9' {
				return nil, false
			}
			n = n*10 + int(r-'0')
		}
		parts = append(parts, n)
	}
	return parts, true
}

// compareClaudeTuiVersionParts lexicographically compares two version part slices,
// returning 1 if a > b, -1 if a < b, 0 if equal.
func compareClaudeTuiVersionParts(a, b []int) int {
	n := len(a)
	if len(b) > n {
		n = len(b)
	}
	for i := 0; i < n; i++ {
		av, bv := 0, 0
		if i < len(a) {
			av = a[i]
		}
		if i < len(b) {
			bv = b[i]
		}
		if av > bv {
			return 1
		}
		if av < bv {
			return -1
		}
	}
	return 0
}

