+func parseClaudeTuiVersionParts(version string) ([]int, bool) {
+	version = strings.ReplaceAll(version, "-", ".")
+	raw := strings.Split(version, ".")
+	if len(raw) == 0 {
+		return nil, false
+	}
+	parts := make([]int, 0, len(raw))
+	for _, part := range raw {
+		if part == "" {
+			return nil, false
+		}
+		n := 0
+		for _, r := range part {
+			if r < '0' || r > '9' {
+				return nil, false
+			}
+			n = n*10 + int(r-'0')
+		}
+		parts = append(parts, n)
+	}
+	return parts, true
